	// Flow-style YAML mapping on disk.
	fm, ok2 := additiveMerge([]byte("{name: x}\n"), []byte("name: x\nextra: 1\n"))
	fmt.Printf("flow mapping: merged=%v out=%q\n", ok2, string(fm))
